              "outOfScope": false,
              "reasonOutOfScope": "",
              "threats": [
                {
                  "id": "e64bb246-dded-4261-b91b-c7cbed2a7376",
                  "title": "Admin account takeover via AiTM phishing + weak MFA",
                  "status": "Open",
                  "severity": "Critical",
                  "type": "Spoofing",
                  "description": "Phishing AND weak MFA AND MITM: adversary-in-the-middle kit steals session cookie, or MFA push fatigue gets a prompt accepted. 16 standing admin accounts multiply the targets.",
                  "mitigation": "Phishing-resistant MFA (FIDO2/passkeys), number matching, cut standing admins via just-in-time PAM, conditional access, session binding.",
                  "modelType": "STRIDE",
                  "new": false,
                  "number": 3,
                  "score": ""
