              "description": "Authorises payments with the acquirer",
              "outOfScope": false,
              "reasonOutOfScope": "",
              "threats": [
                {
                  "id": "36ed7701-6bd8-43b9-a64f-efcd75ff1384",
                  "title": "Log4Shell remote code execution",
                  "status": "Open",
                  "severity": "Critical",
                  "type": "Elevation of privilege",
                  "description": "Unpatched Log4j (CVE-2021-44228) lets an attacker run code on the payment server via a crafted string in any logged field.",
                  "mitigation": "Patch Log4j >= 2.17.1, SBOM + dependency scanning, WAF virtual patch, block outbound LDAP/JNDI egress.",
                  "modelType": "STRIDE",
